contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(depositAmount > 0);
        require(depositAmount <= address(this).balance);

        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        uint cBalanceBefore = address(c).balance;

        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;
        uint recordedAfterDeposit = c.balances(address(this)); if (__ESBMC_reverted()) return;

        require(recordedAfterDeposit >= collectAmount);

        uint cBalanceBeforeCollect = address(c).balance;
        bool collectReverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            collectReverted = true;
        } else {
            collectReverted = false;
        }

        uint recordedAfterCollect = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cBalanceAfterCollect = address(c).balance;

        assert(!collectReverted && recordedAfterCollect == recordedAfterDeposit - collectAmount && cBalanceAfterCollect == cBalanceBeforeCollect - collectAmount && cBalanceAfterCollect - recordedAfterCollect == cBalanceBefore);
    }

    receive() external payable {}
}

