pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 depositAmount, uint256 collectAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depositAmount > 0);
        vm.assume(depositAmount <= address(this).balance);
        try c.SetMinSum(0) {} catch { return; }
        try c.Initialized() {} catch { return; }
        uint cBalanceBefore = address(c).balance;
        try c.Deposit{value: depositAmount}() {} catch { return; }
        uint256 recordedAfterDeposit;
        try c.balances(address(this)) returns (uint256 __r) { recordedAfterDeposit = __r; } catch { return; }
        vm.assume(recordedAfterDeposit >= collectAmount);
        uint cBalanceBeforeCollect = address(c).balance;
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }
        uint256 recordedAfterCollect;
        try c.balances(address(this)) returns (uint256 __r) { recordedAfterCollect = __r; } catch { return; }
        uint cBalanceAfterCollect = address(c).balance;
        assertTrue(!collectReverted && recordedAfterCollect == recordedAfterDeposit - collectAmount && cBalanceAfterCollect == cBalanceBeforeCollect - collectAmount && cBalanceAfterCollect - recordedAfterCollect == cBalanceBefore);
    }

    function testFuzz_run(uint256 depositAmount, uint256 collectAmount) public {
        _run(depositAmount, collectAmount);
    }

    receive() external payable {}
}
